def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    threat_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if opp.get('budget', 0) > 0:
                threat_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    base = DAILY_SALARY * 0.42

    if scarcity == 2:
        base = DAILY_SALARY * 0.72
    elif scarcity == 1:
        base = DAILY_SALARY * 0.56

    if hp <= 2 or no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.68)

    if urgent_opponents >= 2:
        base += 6.0
    elif urgent_opponents == 1:
        base += 3.0

    if rich_opponents >= 2 and scarcity >= 1:
        base += 4.0

    if highest_threat >= DAILY_SALARY * 1.2:
        if hp >= 5 and no_water_days == 0 and supply >= 20:
            base = min(base, DAILY_SALARY * 0.38)
        else:
            base = max(base, DAILY_SALARY * 0.82)
    elif highest_threat >= DAILY_SALARY * 0.85:
        if hp >= 6 and no_water_days == 0 and supply >= 20:
            base = min(base, DAILY_SALARY * 0.4)
        else:
            base = max(base, highest_threat * 0.78)
    elif highest_threat > 0:
        base = max(base, min(highest_threat + 2.0, DAILY_SALARY * 0.88))
    else:
        base = max(base, avg_prev + 1.5)

    if day >= 8:
        base += 4.0
    if day >= 9 and hp <= 4:
        base += 8.0

    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = DAILY_SALARY * 1.2
    elif day <= 8:
        reserve_floor = DAILY_SALARY * 0.7

    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor + min(reserve_floor * 0.25, DAILY_SALARY * 0.3)

    bid = min(base, affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.95))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta_round_state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If I'm the only one left, bid minimally to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Analyze yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = DAILY_SALARY * 0.5 # Default moderate bid

    # Adjust bid based on HP and opponent behavior
    # Critical HP: Must get water
    if my_status['hp'] <= 2:
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            bid = max(DAILY_SALARY * 0.9, highest_prev_bid + 5.0)
        else:
            bid = DAILY_SALARY * 0.85 # High but not max
    # Low HP: Prefer to get water
    elif my_status['hp'] <= 4:
        if highest_prev_bid >= DAILY_SALARY * 0.6:
            bid = max(DAILY_SALARY * 0.75, highest_prev_bid + 2.0)
        else:
            bid = DAILY_SALARY * 0.65
    # Healthy HP: Can be more conservative
    else:
        if highest_prev_bid >= DAILY_SALARY * 0.8: # Opponents very aggressive
            bid = DAILY_SALARY * 0.4 # Let them overspend, I'm healthy
        elif highest_prev_bid > 0.0: # Opponents bid something
            bid = max(DAILY_SALARY * 0.3, highest_prev_bid * 0.9) # Try to get it cheaper
        else:
            bid = DAILY_SALARY * 0.35 # Default conservative bid

    # Consider the day: Bids might increase towards the end of the episode
    days_remaining = EPISODE_DAYS - day_context['day']
    if days_remaining <= 3: # Last few days, more aggressive
        bid = max(bid, DAILY_SALARY * 0.7)

    # Consider supply vs demand
    total_water_needed = WATER_REQ # My water requirement
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    # If supply is tight compared to total demand, competition is high
    if day_context['supply'] < total_water_needed and num_alive_opponents > 0:
        if my_status['hp'] <= 3:
            bid = max(bid, DAILY_SALARY * 0.95) # Critical, bid very high
        elif my_status['hp'] <= 5:
            bid = max(bid, DAILY_SALARY * 0.8) # Low, bid high
        else:
            bid = max(bid, DAILY_SALARY * 0.6) # Healthy, still need to compete

    # Ensure bid doesn't exceed budget and is non-negative
    final_bid = min(my_status['budget'], bid)
    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if hp <= 2:
        # Desperate: must win water
        base_bid = DAILY_SALARY * 0.9
    elif hp >= 5:
        # Healthy: can afford to be frugal
        if yesterday_bids:
            max_yesterday = max(yesterday_bids)
            if max_yesterday >= DAILY_SALARY * 0.7:
                # Aggressive last day; still safe to bid low
                base_bid = DAILY_SALARY * 0.35
            else:
                base_bid = DAILY_SALARY * 0.4
        else:
            base_bid = DAILY_SALARY * 0.4
    else:
        # Moderate health
        if yesterday_bids:
            max_yesterday = max(yesterday_bids)
            if max_yesterday >= DAILY_SALARY * 0.8:
                base_bid = DAILY_SALARY * 0.65
            else:
                base_bid = DAILY_SALARY * 0.5
        else:
            base_bid = DAILY_SALARY * 0.5

    # Adjust for supply scarcity
    avg_supply = (15 + 25) / 2.0
    if supply < avg_supply:
        base_bid *= 1.2  # increase bid when supply low
    elif supply > avg_supply:
        base_bid *= 0.85  # decrease bid when supply high

    # Ensure bid is within budget and at least 0
    bid = min(budget, base_bid)
    bid = max(0, bid)
    # Round to avoid fractional pennies if needed
    bid = round(bid, 2)
    return bid
